import sys
from bisect import bisect_right
from math import isqrt

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    q = data[0]
    queries = data[1:]

    limit = isqrt(max(queries))

    is_prime = bytearray(b"\x01") * (limit + 1)
    if limit >= 0:
        is_prime[0] = 0
    if limit >= 1:
        is_prime[1] = 0

    for i in range(2, isqrt(limit) + 1):
        if is_prime[i]:
            start = i * i
            is_prime[start::i] = b"\x00" * (((limit - start) // i) + 1)

    distinct = bytearray(limit + 1)
    for p in range(2, limit + 1):
        if is_prime[p]:
            for x in range(p, limit + 1, p):
                distinct[x] += 1

    candidates = [n * n for n in range(2, limit + 1) if distinct[n] == 2]

    answers = []
    for a in queries:
        answers.append(str(candidates[bisect_right(candidates, a) - 1]))

    sys.stdout.write("\n".join(answers))

if __name__ == "__main__":
    solve()

import sys


def solve_case(n, k, cakes):
    m = 2 * k

    best_value = [0] * n
    best_label = [0] * n

    for i, (x, y, z) in enumerate(cakes):
        vals = (x, y, z)
        p = max(range(3), key=lambda d: vals[d])
        best_value[i] = vals[p]
        best_label[i] = p

    order = sorted(range(n), key=lambda i: best_value[i], reverse=True)
    selected = set(order[:m])

    base = sum(best_value[i] for i in order[:m])
    base_parity = 0
    for i in order[:m]:
        base_parity ^= 1 << best_label[i]

    # Top three selected items for each (old label, new label),
    # minimizing loss when recolored.
    recolor = [[[] for _ in range(3)] for _ in range(3)]
    for i in selected:
        old = best_label[i]
        vals = cakes[i]
        for new in range(3):
            if new == old:
                continue
            loss = best_value[i] - vals[new]
            arr = recolor[old][new]
            arr.append((loss, i))
            arr.sort()
            if len(arr) > 3:
                arr.pop()

    # Top three selected items for each (old label, new label),
    # minimizing loss in a swap.
    sel_swap = [[[] for _ in range(3)] for _ in range(3)]
    for i in selected:
        old = best_label[i]
        vals = cakes[i]
        for new in range(3):
            loss = best_value[i] - vals[new]
            arr = sel_swap[old][new]
            arr.append((loss, i))
            arr.sort()
            if len(arr) > 3:
                arr.pop()

    # Top three unselected items for each (old label, new label),
    # maximizing gained value.
    uns_swap = [[[] for _ in range(3)] for _ in range(3)]
    for i in range(n):
        if i in selected:
            continue
        old = best_label[i]
        vals = cakes[i]
        for new in range(3):
            gain = vals[new]
            arr = uns_swap[old][new]
            arr.append((-gain, i))
            arr.sort()
            if len(arr) > 3:
                arr.pop()

    even_masks = (3, 5, 6)

    # Candidate single operations, grouped by their parity mask.
    candidates = {mask: [] for mask in even_masks}

    for old in range(3):
        for new in range(3):
            if old == new:
                continue
            mask = (1 << old) ^ (1 << new)
            for loss, idx in recolor[old][new]:
                candidates[mask].append((loss, (idx,)))

    for old_s in range(3):
        for new_s in range(3):
            for old_u in range(3):
                for new_u in range(3):
                    mask = (
                        (1 << old_s) ^ (1 << new_s) ^
                        (1 << old_u) ^ (1 << new_u)
                    )
                    if mask == 0 or mask not in candidates:
                        continue
                    for loss_s, idx_s in sel_swap[old_s][new_s]:
                        for neg_gain_u, idx_u in uns_swap[old_u][new_u]:
                            candidates[mask].append(
                                (loss_s + neg_gain_u, (idx_s, idx_u))
                            )

    for mask in even_masks:
        candidates[mask].sort()
        candidates[mask] = candidates[mask][:1000]

    def best_operation(mask, forbidden):
        if mask == 0:
            return 0, ()

        best = None
        forbidden = set(forbidden)

        # Recolor one selected cake.
        for old in range(3):
            for new in range(3):
                if old == new:
                    continue
                if ((1 << old) ^ (1 << new)) != mask:
                    continue
                for loss, idx in recolor[old][new]:
                    if idx not in forbidden:
                        if best is None or loss < best[0]:
                            best = (loss, (idx,))

        # Swap one selected and one unselected cake.
        for old_s in range(3):
            for new_s in range(3):
                for old_u in range(3):
                    for new_u in range(3):
                        cur_mask = (
                            (1 << old_s) ^ (1 << new_s) ^
                            (1 << old_u) ^ (1 << new_u)
                        )
                        if cur_mask != mask:
                            continue

                        for loss_s, idx_s in sel_swap[old_s][new_s]:
                            if idx_s in forbidden:
                                continue
                            for neg_gain_u, idx_u in uns_swap[old_u][new_u]:
                                if idx_u in forbidden:
                                    continue
                                loss = loss_s + neg_gain_u
                                if best is None or loss < best[0]:
                                    best = (loss, (idx_s, idx_u))

        return best if best is not None else (10**30, ())

    target = base_parity
    min_loss = 10**30

    # One operation.
    loss, _ = best_operation(target, ())
    min_loss = min(min_loss, loss)

    # Two operations.
    for first_mask in even_masks:
        second_mask = target ^ first_mask
        if second_mask not in candidates:
            continue
        for loss1, ids1 in candidates[first_mask]:
            loss2, _ = best_operation(second_mask, ids1)
            min_loss = min(min_loss, loss1 + loss2)

    return base - min_loss


def main():
    input = sys.stdin.buffer.readline
    t = int(input())
    answers = []

    for _ in range(t):
        n, k = map(int, input().split())
        cakes = [tuple(map(int, input().split())) for _ in range(n)]
        answers.append(str(solve_case(n, k, cakes)))

    print("\n".join(answers))


