def solve():
    input = sys.stdin.readline

    n = int(input())
    s = input().strip()
    t = input().strip()

    mapping = [-1] * 26

    for a, b in zip(s, t):
        x = ord(a) - ord('a')
        y = ord(b) - ord('a')
        if mapping[x] == -1:
            mapping[x] = y
        elif mapping[x] != y:
            print(-1)
            return

    changed = sum(
        1 for x in range(26)
        if mapping[x] != -1 and mapping[x] != x
    )

    color = [0] * 26
    cycles = 0

    for start in range(26):
        if mapping[start] == -1 or color[start] != 0:
            continue

        cur = start
        while (
            cur != -1
            and mapping[cur] != -1
            and color[cur] == 0
        ):
            color[cur] = 1
            cur = mapping[cur]

        if (
            cur != -1
            and mapping[cur] != -1
            and color[cur] == 1
        ):
            cycles += 1

        cur = start
        while (
            cur != -1
            and mapping[cur] != -1
            and color[cur] == 1
        ):
            color[cur] = 2
            cur = mapping[cur]

    if cycles > 0 and len(set(t)) == 26:
        print(-1)
    else:
        print(changed + cycles)

