from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def prefix(x: int) -> int:
            total = 0
            start = 1
            steps = 1

            while start <= x:
                end = min(x, start * 4 - 1)
                total += (end - start + 1) * steps
                start *= 4
                steps += 1

            return total

        answer = 0

        for left, right in queries:
            required = prefix(right) - prefix(left - 1)
            answer += (required + 1) // 2

        return answer

import sys

def solve():
    s = sys.stdin.buffer.readline().strip()
    n = len(s)
    rev = s[::-1]

    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and rev[i] != rev[j]:
            j = pi[j - 1]
        if rev[i] == rev[j]:
            j += 1
        pi[i] = j

    matched = 0
    for c in s:
        while matched > 0 and c != rev[matched]:
            matched = pi[matched - 1]
        if c == rev[matched]:
            matched += 1

    answer = s + s[:n - matched][::-1]
    sys.stdout.buffer.write(answer + b"\n")

if __name__ == "__main__":
    solve()

