from functools import lru_cache


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(n: int) -> int:
            if n <= 0:
                return 0

            digits = tuple(map(int, str(n)))
            length = len(digits)
            total = 0

            for target_sum in range(1, 9 * length + 1):
                @lru_cache(None)
                def dp(pos: int, digit_sum: int, product_mod: int,
                       started: bool, tight: bool) -> int:
                    if digit_sum > target_sum:
                        return 0

                    if digit_sum + 9 * (length - pos) < target_sum:
                        return 0

                    if pos == length:
                        return int(
                            started
                            and digit_sum == target_sum
                            and product_mod == 0
                        )

                    limit = digits[pos] if tight else 9
                    result = 0

                    for digit in range(limit + 1):
                        next_tight = tight and (digit == limit)

                        if not started:
                            if digit == 0:
                                result += dp(
                                    pos + 1,
                                    digit_sum,
                                    1,
                                    False,
                                    next_tight
                                )
                            else:
                                result += dp(
                                    pos + 1,
                                    digit_sum + digit,
                                    digit % target_sum,
                                    True,
                                    next_tight
                                )
                        else:
                            result += dp(
                                pos + 1,
                                digit_sum + digit,
                                (product_mod * digit) % target_sum,
                                True,
                                next_tight
                            )

                    return result

                total += dp(0, 0, 1, False, True)

            return total

        return count_up_to(r) - count_up_to(l - 1)

import sys
from collections import deque

sys.setrecursionlimit(1_000_000)


class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        self.g[fr].append([to, cap, len(self.g[to])])
        self.g[to].append([fr, 0, len(self.g[fr]) - 1])

    def max_flow(self, s, t):
        flow = 0
        INF = 10**18

        while True:
            level = [-1] * self.n
            q = deque([s])
            level[s] = 0

            while q:
                v = q.popleft()
                for to, cap, rev in self.g[v]:
                    if cap > 0 and level[to] < 0:
                        level[to] = level[v] + 1
                        q.append(to)

            if level[t] < 0:
                break

            it = [0] * self.n

            def dfs(v, f):
                if v == t:
                    return f

                while it[v] < len(self.g[v]):
                    i = it[v]
                    to, cap, rev = self.g[v][i]

                    if cap > 0 and level[v] + 1 == level[to]:
                        d = dfs(to, min(f, cap))
                        if d:
                            self.g[v][i][1] -= d
                            self.g[to][rev][1] += d
                            return d

                    it[v] += 1

                return 0

            while True:
                f = dfs(s, INF)
                if f == 0:
                    break
                flow += f

        return flow


def main():
    input = sys.stdin.readline
    N, M, K = map(int, input().split())
    edges = []

    for _ in range(M):
        u, v = map(int, input().split())
        edges.append((u - 1, v - 1))

    INF = 10**9

    def feasible(L):
        if L == 0:
            return True

        layer_nodes = N * L
        source = layer_nodes
        sink = layer_nodes + 1
        dinic = Dinic(layer_nodes + 2)

        def node(v, level):
            return v * L + (level - 1)

        # Vertex labels must be nondecreasing across levels:
        # label[v] >= i implies label[v] >= i-1.
        for v in range(N):
            for level in range(2, L + 1):
                dinic.add_edge(node(v, level), node(v, level - 1), INF)

        # Force label[1] = 0 and label[N] = L.
        for level in range(1, L + 1):
            dinic.add_edge(node(0, level), sink, INF)
            dinic.add_edge(source, node(N - 1, level), INF)

        for u, v in edges:
            # An edge cannot increase the label by more than one:
            # label[v] >= i implies label[u] >= i-1.
            for level in range(2, L + 1):
                dinic.add_edge(node(v, level), node(u, level - 1), INF)

            # Cost 1 exactly when this edge increases the label by one.
            for level in range(1, L + 1):
                dinic.add_edge(node(v, level), node(u, level), 1)

        return dinic.max_flow(source, sink) <= K

    low, high = 0, N
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)


if __name__ == "__main__":
    main()

import sys


def contains(intervals, x):
    lo, hi = 0, len(intervals)
    while lo < hi:
        mid = (lo + hi) // 2
        if intervals[mid][1] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo < len(intervals) and intervals[lo][0] <= x


def has_pair(a, b, target):
    i = j = 0
    while i < len(a) and j < len(b):
        al, ar = a[i]
        bl, br = b[j]

        left = max(al, target - br)
        right = min(ar, target - bl)
        if left <= right:
            return True

        if ar < target - bl:
            i += 1
        else:
            j += 1
    return False


def merge_intervals(lists):
    all_intervals = []
    for arr in lists:
        all_intervals.extend(arr)

    if not all_intervals:
        return []

    all_intervals.sort()
    result = [list(all_intervals[0])]

    for l, r in all_intervals[1:]:
        if l <= result[-1][1] + 1:
            if r > result[-1][1]:
                result[-1][1] = r
        else:
            result.append([l, r])

    return [tuple(x) for x in result]


def solve():
    input = sys.stdin.buffer.readline
    N, K = map(int, input().split())
    V = N * K

    graph = [[] for _ in range(V)]
    for _ in range(V - 1):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        graph[u].append(v)
        graph[v].append(u)

    if K == 1:
        print("Yes")
        return

    parent = [-1] * V
    order = [0]
    parent[0] = V

    for v in order:
        for to in graph[v]:
            if to != parent[v]:
                parent[to] = v
                order.append(to)

    complete = [False] * V
    open_intervals = [None] * V

    target = K - 1

    for v in reversed(order):
        children = [to for to in graph[v] if parent[to] == v]
        bad = [to for to in children if not complete[to]]

        child_intervals = {}
        for to in children:
            if open_intervals[to] is not None:
                child_intervals[to] = open_intervals[to]

        can_open = False
        open_parts = []

        if len(bad) <= 1:
            if len(bad) == 0:
                can_open = True
                open_parts.append([(1, 1)])
                for to in children:
                    arr = child_intervals.get(to)
                    if arr is not None:
                        open_parts.append([(l + 1, r + 1) for l, r in arr])
            else:
                arr = child_intervals.get(bad[0])
                if arr is not None:
                    can_open = True
                    open_parts.append([(l + 1, r + 1) for l, r in arr])

        if can_open:
            open_intervals[v] = merge_intervals(open_parts)
            if not open_intervals[v]:
                open_intervals[v] = None
        else:
            open_intervals[v] = None

        can_complete = False

        # A path from v through exactly one child.
        if len(bad) <= 1:
            if len(bad) == 0:
                candidates = children
            else:
                candidates = bad

            for to in candidates:
                arr = child_intervals.get(to)
                if arr is not None and contains(arr, target):
                    can_complete = True
                    break

        # A path from v through exactly two children.
        if not can_complete and len(bad) <= 2:
            if len(bad) == 2:
                a = child_intervals.get(bad[0])
                b = child_intervals.get(bad[1])
                if a is not None and b is not None and has_pair(a, b, target):
                    can_complete = True

            elif len(bad) == 1:
                b = child_intervals.get(bad[0])
                if b is not None:
                    for to in children:
                        if to == bad[0]:
                            continue
                        a = child_intervals.get(to)
                        if a is not None and has_pair(a, b, target):
                            can_complete = True
                            break

            else:
                seen = []
                for to in children:
                    a = child_intervals.get(to)
                    if a is None:
                        continue

                    if seen and has_pair(a, seen, target):
                        can_complete = True
                        break

                    seen = merge_intervals([seen, a]) if seen else a

        complete[v] = can_complete

    print("Yes" if complete[0] else "No")


