import sys


def runs(s):
    res = []
    start = 0
    n = len(s)
    for i in range(1, n + 1):
        if i == n or s[i] != s[start]:
            res.append((s[start], i - start))
            start = i
    return res


def normalize(s, X, Y):
    stack = []
    pending = runs(s)

    while pending:
        c, length = pending.pop()

        if length <= 0:
            continue

        if stack and stack[-1][0] == c:
            stack[-1] = (c, stack[-1][1] + length)
        else:
            stack.append((c, length))

        while len(stack) >= 2:
            c2, b = stack[-1]
            c1, a = stack[-2]

            if c1 != '0' or c2 != '1' or a < X or b < Y:
                break

            stack.pop()
            stack.pop()

            pieces = (
                ('0', a - X),
                ('1', Y),
                ('0', X),
                ('1', b - Y),
            )

            for piece in reversed(pieces):
                if piece[1] > 0:
                    pending.append(piece)

            break

    return stack


def main():
    input = sys.stdin.readline

    N, X, Y = map(int, input().split())
    S = input().strip()
    T = input().strip()

    if normalize(S, X, Y) == normalize(T, X, Y):
        print("Yes")
    else:
        print("No")


if __name__ == "__main__":
    main()

import sys

MOD = 998244353

def solve():
    input = sys.stdin.readline
    n = int(input())
    s = input().strip()

    max_nodes = n // 2 + 1
    fact = [1] * (max_nodes + 1)
    for i in range(1, max_nodes + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (max_nodes + 1)
    invfact[max_nodes] = pow(fact[max_nodes], MOD - 2, MOD)
    for i in range(max_nodes, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    type_id = {}
    ways = []

    # Each stack entry is the list of child type IDs of one currently open node.
    stack = [[]]

    for ch in s:
        if ch == '(':
            stack.append([])
        else:
            children = stack.pop()
            key = tuple(sorted(children))

            if key not in type_id:
                idx = len(ways)
                type_id[key] = idx

                k = len(key)
                value = fact[k]
                prev = -1
                cnt = 0

                for child in key:
                    value = value * ways[child] % MOD
                    if child == prev:
                        cnt += 1
                    else:
                        if prev != -1:
                            value = value * invfact[cnt] % MOD
                        prev = child
                        cnt = 1

                if prev != -1:
                    value = value * invfact[cnt] % MOD

                ways.append(value)

            stack[-1].append(type_id[key])

    roots = sorted(stack[0])
    answer = fact[len(roots)]

    prev = -1
    cnt = 0
    for root in roots:
        answer = answer * ways[root] % MOD
        if root == prev:
            cnt += 1
        else:
            if prev != -1:
                answer = answer * invfact[cnt] % MOD
            prev = root
            cnt = 1

    if prev != -1:
        answer = answer * invfact[cnt] % MOD

    print(answer)

if __name__ == "__main__":
    solve()

from typing import List


class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        by_right = [[] for _ in range(n + 1)]

        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, idx))

        gains = [0] * m
        total = 0

        top_value = 0
        top_id = -1
        second_value = 0

        for right in range(1, n + 1):
            for value, idx in by_right[right]:
                if value >= top_value:
                    second_value = top_value
                    top_value = value
                    top_id = idx
                elif value > second_value:
                    second_value = value

            total += right - top_value

            if top_value > second_value:
                gains[top_id] += top_value - second_value

        return total + max(gains)

import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    idx = 2

    for _ in range(m):
        x, y, z = data[idx] - 1, data[idx + 1] - 1, data[idx + 2]
        idx += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    xor_value = [-1] * n
    answer = [0] * n
    bit_limit = 31

    for start in range(n):
        if xor_value[start] != -1:
            continue

        xor_value[start] = 0
        stack = [start]
        component = []
        bit_count = [0] * bit_limit

        while stack:
            v = stack.pop()
            component.append(v)

            value = xor_value[v]
            for b in range(bit_limit):
                if (value >> b) & 1:
                    bit_count[b] += 1

            for to, z in graph[v]:
                expected = value ^ z
                if xor_value[to] == -1:
                    xor_value[to] = expected
                    stack.append(to)
                elif xor_value[to] != expected:
                    print(-1)
                    return

        size = len(component)
        shift = 0
        for b in range(bit_limit):
            if bit_count[b] * 2 > size:
                shift |= 1 << b

        for v in component:
            answer[v] = xor_value[v] ^ shift

    print(*answer)


