class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        total = n + m - 1

        forced = [-1] * total

        # Apply all mandatory occurrences.
        for start in range(n):
            if str1[start] == 'T':
                for k, ch in enumerate(str2):
                    pos = start + k
                    value = ord(ch)
                    if forced[pos] != -1 and forced[pos] != value:
                        return ""
                    forced[pos] = value

        satisfied = [False] * n
        last_free_buckets = [[] for _ in range(total)]

        # Determine which F-windows are already satisfied and
        # their last position not fixed by a T-window.
        for start in range(n):
            if str1[start] == 'F':
                last_free = -1
                already_diff = False

                for k, ch in enumerate(str2):
                    pos = start + k
                    if forced[pos] == -1:
                        last_free = pos
                    elif forced[pos] != ord(ch):
                        already_diff = True

                if last_free == -1:
                    if not already_diff:
                        return ""
                    satisfied[start] = True
                else:
                    satisfied[start] = already_diff
                    last_free_buckets[last_free].append(start)

        result = [''] * total

        for pos in range(total):
            if forced[pos] != -1:
                value = chr(forced[pos])
            else:
                forbidden = set()

                # Every unsatisfied F-window whose last free position is
                # this position must differ from str2 at this position.
                for start in last_free_buckets[pos]:
                    if not satisfied[start]:
                        forbidden.add(str2[pos - start])

                value = None
                for code in range(ord('a'), ord('z') + 1):
                    ch = chr(code)
                    if ch not in forbidden:
                        value = ch
                        break

                if value is None:
                    return ""

            result[pos] = value

            # Update all F-windows containing this position.
            if forced[pos] == -1:
                left = max(0, pos - m + 1)
                right = min(n - 1, pos)
                for start in range(left, right + 1):
                    if str1[start] == 'F' and not satisfied[start]:
                        if value != str2[pos - start]:
                            satisfied[start] = True

        return ''.join(result)

from typing import List


class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        limit = k

        factorial = [1] * (n + 1)
        for i in range(1, n + 1):
            factorial[i] = min(limit, factorial[i - 1] * i)

        def count_completions(odd_left: int, even_left: int, next_parity: int) -> int:
            length = odd_left + even_left
            if length == 0:
                return 1

            if next_parity == 1:  # Odd must be placed next
                if odd_left != (length + 1) // 2 or even_left != length // 2:
                    return 0
            else:  # Even must be placed next
                if even_left != (length + 1) // 2 or odd_left != length // 2:
                    return 0

            return min(limit, factorial[odd_left] * factorial[even_left])

        available = list(range(1, n + 1))
        odd_left = (n + 1) // 2
        even_left = n // 2
        result = []
        previous_parity = None

        for _ in range(n):
            chosen_index = -1

            for i, value in enumerate(available):
                parity = value % 2

                if previous_parity is not None and parity == previous_parity:
                    continue

                new_odd = odd_left - (parity == 1)
                new_even = even_left - (parity == 0)
                completions = count_completions(new_odd, new_even, 1 - parity)

                if k > completions:
                    k -= completions
                else:
                    chosen_index = i
                    odd_left = new_odd
                    even_left = new_even
                    previous_parity = parity
                    result.append(value)
                    break

            if chosen_index == -1:
                return []

            available.pop(chosen_index)

        return result

