import sys
from bisect import bisect_right


def solve_case(n, a, b):
    xs = [i + 1 for i, c in enumerate(a) if c == '1']
    ys = [i + 1 for i, c in enumerate(b) if c == '1']

    m = len(xs)
    q = len(ys)

    if q > m:
        return -1

    gaps = [xs[i + 1] - xs[i] for i in range(m - 1)]

    size = 1
    while size < max(1, m - 1):
        size <<= 1

    seg = [0] * (2 * size)
    for i, v in enumerate(gaps):
        seg[size + i] = v
    for i in range(size - 1, 0, -1):
        seg[i] = max(seg[i << 1], seg[i << 1 | 1])

    def rightmost_at_least(left, right, value):
        if left > right:
            return -1

        l = left + size
        r = right + size + 1
        left_nodes = []
        right_nodes = []

        while l < r:
            if l & 1:
                left_nodes.append(l)
                l += 1
            if r & 1:
                r -= 1
                right_nodes.append(r)
            l >>= 1
            r >>= 1

        for node in right_nodes:
            if seg[node] >= value:
                while node < size:
                    rc = node << 1 | 1
                    lc = node << 1
                    if seg[rc] >= value:
                        node = rc
                    else:
                        node = lc
                return node - size

        for node in reversed(left_nodes):
            if seg[node] >= value:
                while node < size:
                    rc = node << 1 | 1
                    lc = node << 1
                    if seg[rc] >= value:
                        node = rc
                    else:
                        node = lc
                return node - size

        return -1

    def feasible(k):
        start = 0

        for t in range(q - 1):
            target = ys[t]

            if not (target - k <= xs[start] <= target + k):
                return False

            current_right = bisect_right(xs, target + k) - 1
            next_right = bisect_right(xs, ys[t + 1] + k) - 1

            right = min(current_right, next_right - 1)
            if right < start:
                return False

            boundary = rightmost_at_least(
                start, right, ys[t + 1] - target
            )
            if boundary < 0:
                return False

            start = boundary + 1

        last = ys[-1]
        return start < m and xs[start] >= last - k and xs[-1] <= last + k

    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1

    return lo if feasible(lo) else -1


