class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        groups = [[] for _ in range(4)]

        for x, y in points:
            if y == 0:
                groups[0].append(x)              # bottom: left -> right
            elif x == side:
                groups[1].append(y)              # right: bottom -> top
            elif y == side:
                groups[2].append(side - x)       # top: right -> left
            else:
                groups[3].append(side - y)       # left: top -> bottom

        for g in groups:
            g.sort()

        def feasible(dist: int) -> bool:
            # No answer larger than side is possible when k >= 4:
            # if dist > side, each side contributes at most two points,
            # while four occupied sides are impossible by the cyclic
            # adjacent-side inequalities.
            if dist > side:
                return False

            q = dist - side

            for mask in range(1, 16):
                occupied = [i for i in range(4) if mask & (1 << i)]
                if sum(len(groups[i]) for i in occupied) < k:
                    continue

                first_side = occupied[0]
                order = occupied

                # dp_prev[j][c] = maximum coordinate of the first selected
                # point on first_side, among ways ending at point j with c
                # selected points.
                dp_prev = None
                prev_points = None

                for pos, sidx in enumerate(order):
                    arr = groups[sidx]
                    m = len(arr)

                    if pos == 0:
                        dp_cur = [[-1] * (k + 1) for _ in range(m)]
                        for j in range(m):
                            dp_cur[j][1] = arr[j]
                    else:
                        prev_arr = groups[order[pos - 1]]
                        prev_m = len(prev_arr)

                        adjacent = ((order[pos - 1] + 1) % 4 == sidx)

                        # Aggregate states when the previous occupied side
                        # is opposite or otherwise non-adjacent.
                        unrestricted = [-1] * (k + 1)
                        for j in range(prev_m):
                            row = dp_prev[j]
                            for c in range(1, k + 1):
                                if row[c] > unrestricted[c]:
                                    unrestricted[c] = row[c]

                        # Prefix maxima for transitions from the previous side
                        # when the sides are adjacent.
                        cross_prefix = [[-1] * (k + 1) for _ in range(prev_m)]
                        best = [-1] * (k + 1)
                        for j in range(prev_m):
                            row = dp_prev[j]
                            for c in range(1, k + 1):
                                if row[c] > best[c]:
                                    best[c] = row[c]
                                cross_prefix[j][c] = best[c]

                        dp_cur = [[-1] * (k + 1) for _ in range(m)]

                        # Prefix maxima of states already selected on this
                        # same side, usable when their coordinate differs
                        # by at least dist.
                        same_best = [-1] * (k + 1)
                        same_ptr = 0

                        for j, x in enumerate(arr):
                            while same_ptr < j and arr[same_ptr] <= x - dist:
                                row = dp_cur[same_ptr]
                                for c in range(1, k + 1):
                                    if row[c] > same_best[c]:
                                        same_best[c] = row[c]
                                same_ptr += 1

                            row = dp_cur[j]

                            # Add a point after selections on the previous
                            # occupied side.
                            for c in range(1, k):
                                value = unrestricted[c]
                                if adjacent:
                                    limit = x - q
                                    p = 0
                                    while p < prev_m and prev_arr[p] <= limit:
                                        p += 1
                                    if p:
                                        cross_value = cross_prefix[p - 1][c]
                                        if cross_value > value:
                                            value = cross_value

                                if value > row[c + 1]:
                                    row[c + 1] = value

                            # Add a point after earlier points on this side.
                            for c in range(1, k):
                                if same_best[c] > row[c + 1]:
                                    row[c + 1] = same_best[c]

                    dp_prev = dp_cur
                    prev_points = arr

                # Check the cyclic connection from the last occupied side
                # back to the first occupied side.
                last_side = order[-1]
                cyclic_adjacent = ((last_side + 1) % 4 == first_side)

                for j, last_coord in enumerate(prev_points):
                    first_coord = dp_prev[j][k]
                    if first_coord < 0:
                        continue

                    if not cyclic_adjacent or first_coord >= last_coord + q:
                        return True

            return False

        low, high = 0, side + 1
        while low + 1 < high:
            mid = (low + high) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid

        return low

