    if not data:
        return

    n = data[0]
    adj = [[] for _ in range(n)]
    idx = 1
    for _ in range(n - 1):
        a = data[idx] - 1
        b = data[idx + 1] - 1
        idx += 2
        adj[a].append(b)
        adj[b].append(a)

    parent = [-2] * n
    parent[0] = -1
    order = [0]

    for v in order:
        for u in adj[v]:
            if u != parent[v]:
                parent[u] = v
                order.append(u)

    # down[v] = maximum valid branch rooted at v, assuming its parent edge is used
    down = [1] * n
    for v in reversed(order):
        vals = [down[u] for u in adj[v] if parent[u] == v]
        if len(vals) >= 3:
            vals.sort(reverse=True)
            down[v] = 1 + vals[0] + vals[1] + vals[2]

    # up[v] = corresponding branch value from parent[v] to v
    up = [0] * n
    answer = -1

    for v in order:
        incoming = [down[u] for u in adj[v] if parent[u] == v]
        if parent[v] != -1:
            incoming.append(up[v])

        top = sorted(incoming, reverse=True)[:4]

        if len(incoming) >= 4:
            answer = max(answer, 1 + sum(top))

        for u in adj[v]:
            if parent[u] != v:
                continue

            value = down[u]
            removed = False
            remaining = []

            for x in top:
                if not removed and x == value:
                    removed = True
                else:
                    remaining.append(x)

            if len(remaining) >= 3:
                up[u] = 1 + remaining[0] + remaining[1] + remaining[2]
            else:
                up[u] = 1

    print(answer)

