class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        x, y, z = p.split("*")

        def build_lps(pattern):
            m = len(pattern)
            lps = [0] * m
            length = 0
            i = 1
            while i < m:
                if pattern[i] == pattern[length]:
                    length += 1
                    lps[i] = length
                    i += 1
                elif length:
                    length = lps[length - 1]
                else:
                    i += 1
            return lps

        def find_occurrences(pattern):
            m = len(pattern)
            found = [False] * (n + 1)
            if m == 0:
                return found

            lps = build_lps(pattern)
            j = 0

            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = lps[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    found[i - m + 1] = True
                    j = lps[j - 1]

            return found

        def build_next(pattern):
            if not pattern:
                return None

            found = find_occurrences(pattern)
            nxt = [n + 1] * (n + 2)
            latest = n + 1

            for i in range(n, -1, -1):
                if found[i]:
                    latest = i
                nxt[i] = latest

            return nxt

        x_occurs = find_occurrences(x) if x else None
        next_y = build_next(y)
        next_z = build_next(z)

        answer = n + 1
        x_len = len(x)
        y_len = len(y)
        z_len = len(z)

        for start in range(n + 1):
            if x:
                if start + x_len > n or not x_occurs[start]:
                    continue

            after_x = start + x_len

            if y:
                y_start = next_y[after_x]
                if y_start > n:
                    continue
                after_y = y_start + y_len
            else:
                after_y = after_x

            if z:
                z_start = next_z[after_y]
                if z_start > n:
                    continue
            else:
                z_start = after_y

            length = z_start + z_len - start
            if length < answer:
                answer = length
                if answer == 0:
                    return 0

        return -1 if answer == n + 1 else answer

