MOD = 998244353

def main():
    W, H, L, R, D, U = map(int, sys.stdin.buffer.read().split())

    n = W + H + 6
    fact = [1] * n
    for i in range(1, n):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * n
    invfact[-1] = pow(fact[-1], MOD - 2, MOD)
    for i in range(n - 1, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def comb(a, b):
        if b < 0 or b > a:
            return 0
        return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD

    def q_back(a, b):
        # Paths from any point in [0,a] x [0,b] to (a,b)
        return (comb(a + b + 2, a + 1) - 1) % MOD

    def q_forward(a, b):
        # Paths from (0,0) to any point in [0,a] x [0,b]
        return (comb(a + b + 2, a + 1) - 1) % MOD

    def suffix(x, y):
        return q_forward(W - x, H - y)

    # Total number of paths in the whole town without the removed rectangle.
    total = (
        comb(W + H + 4, W + 2)
        - (W + 3)
        - (H + 1) * (W + 2)
    ) % MOD

    # Base contribution: paths starting at any point of the removed rectangle.
    # For fixed y, sum suffix(x,y) over x=L..R by hockey-stick identity.
    forbidden = 0
    width = R - L + 1

    for y in range(D, U + 1):
        high = comb(W + H - L - y + 3, W - L + 1)
        low = comb(W + H - R - y + 2, W - R)
        row_sum = (high - low - width) % MOD
        forbidden = (forbidden + row_sum) % MOD

    # Paths whose first removed point is entered from the left boundary.
    if L > 0:
        for y in range(D, U + 1):
            entry = q_back(L - 1, y)
            forbidden = (forbidden + entry * suffix(L, y)) % MOD

    # Paths whose first removed point is entered from the bottom boundary.
    if D > 0:
        for x in range(L + 1, R + 1):
            entry = q_back(x, D - 1)
            forbidden = (forbidden + entry * suffix(x, D)) % MOD

    answer = (total - forbidden) % MOD
    print(answer)

