class Solution:
    def countSubstrings(self, s: str) -> int:
        transitions = [None] * 10
        single = [None] * 10

        for mod in range(1, 10):
            transitions[mod] = [
                [(r * 10 + digit) % mod for r in range(mod)]
                for digit in range(10)
            ]
            single[mod] = [digit % mod for digit in range(10)]

        counts = [None] + [[0] * mod for mod in range(1, 10)]
        answer = 0

        for ch in s:
            digit = ord(ch) - ord('0')

            for mod in range(1, 10):
                old = counts[mod]
                new = [0] * mod
                mapping = transitions[mod][digit]

                for r in range(mod):
                    new[mapping[r]] += old[r]

                new[single[mod][digit]] += 1
                counts[mod] = new

            if digit != 0:
                answer += counts[digit][0]

        return answer

