    states = 1 << N

    rows = [[0] * (N + 1) for _ in range(states)]
    for mask in range(states):
        value = 0
        for i in range(1, N + 1):
            if mask & (1 << (i - 1)):
                value += 1
            rows[mask][i] = value

    trans = [[0] * states for _ in range(26)]

    for c in range(26):
        for mask in range(states):
            old = rows[mask]
            new = [0] * (N + 1)

            for i in range(1, N + 1):
                best = max(
                    old[i],
                    new[i - 1],
                    old[i - 1] + (1 if S[i - 1] == c else 0)
                )
                new[i] = best

            next_mask = 0
            for i in range(1, N + 1):
                if new[i] > new[i - 1]:
                    next_mask |= 1 << (i - 1)

            trans[c][mask] = next_mask

    dp = [0] * states
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * states
        for mask, count in enumerate(dp):
            if count == 0:
                continue
            for c in range(26):
                nxt = trans[c][mask]
                ndp[nxt] = (ndp[nxt] + count) % MOD
        dp = ndp

    ans = [0] * (N + 1)
    for mask, count in enumerate(dp):
        ans[mask.bit_count()] = (ans[mask.bit_count()] + count) % MOD

    print(*ans)

if __name__ == "__main__":
    main()

import sys
from bisect import bisect_left

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, x = data[0], data[1]

    groups = [[], [], []]
    totals = [0, 0, 0]

    pos = 2
    for _ in range(n):
        v, a, c = data[pos], data[pos + 1], data[pos + 2]
        pos += 3
        groups[v - 1].append((a, c))
        totals[v - 1] += a

    dp_groups = []

    for items in groups:
        dp = [0] * (x + 1)
        for a, c in items:
            for capacity in range(x, c - 1, -1):
                candidate = dp[capacity - c] + a
                if candidate > dp[capacity]:
                    dp[capacity] = candidate

        best = 0
        for capacity in range(x + 1):
            if dp[capacity] < best:
                dp[capacity] = best
            else:
                best = dp[capacity]

        dp_groups.append(dp)

    def feasible(target):
        total_cost = 0
        for dp in dp_groups:
            cost = bisect_left(dp, target)
            total_cost += cost
            if total_cost > x:
                return False
        return True

    low = 0
    high = min(totals) + 1

    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)

if __name__ == "__main__":
    solve()

from typing import List


class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        limit = k + 1

        def pair_count(a: int, b: int) -> int:
            def triangular(x: int) -> int:
                return x * (x - 1) // 2 if x > 1 else 0

            return (
                triangular(limit)
                - triangular(limit - a)
                - triangular(limit - b)
                + triangular(limit - a - b)
            )

        def contribution(is_max: bool) -> int:
            prev = [-1] * n
            nxt = [n] * n
            stack = []

            if is_max:
                for i, value in enumerate(nums):
                    while stack and nums[stack[-1]] <= value:
                        stack.pop()
                    if stack:
                        prev[i] = stack[-1]
                    stack.append(i)

                stack.clear()
                for i in range(n - 1, -1, -1):
                    value = nums[i]
                    while stack and nums[stack[-1]] <= value:
                        stack.pop()
                    if stack:
                        nxt[i] = stack[-1]
                    stack.append(i)
            else:
                for i, value in enumerate(nums):
                    while stack and nums[stack[-1]] >= value:
                        stack.pop()
                    if stack:
                        prev[i] = stack[-1]
                    stack.append(i)

                stack.clear()
                for i in range(n - 1, -1, -1):
                    value = nums[i]
                    while stack and nums[stack[-1]] >= value:
                        stack.pop()
                    if stack:
                        nxt[i] = stack[-1]
                    stack.append(i)

            total = 0
            for i, value in enumerate(nums):
                left = i - prev[i]
                right = nxt[i] - i
                total += value * pair_count(left, right)

            return total

        return contribution(True) + contribution(False)

import sys
from math import comb

def solve():
    N, P = map(int, sys.stdin.readline().split())
    n = N // 2
    max_edges = N * (N - 1) // 2

    # dp[(used_even, used_odd, previous_level_size, next_parity)]
    # next_parity: 0 -> next level is odd, 1 -> next level is even
    dp = {(1, 0, 1, 0): [1]}

    final_polys = []

    for total in range(1, 2 * n + 1):
        current = [key for key in dp if key[0] + key[1] == total]

        for key in current:
            a, b, prev, next_parity = key
            poly = dp[key]

            if a == n and b == n:
                final_polys.append(poly)
                continue

            if next_parity == 0:
                remaining = n - b
                if remaining == 0:
                    continue
                for s in range(1, remaining + 1):
                    na, nb = a, b + s
                    ways = comb(remaining, s) % P
                    new_turn = 1
                    new_key = (na, nb, s, new_turn)

                    dest = dp.get(new_key)
                    if dest is None:
                        dest = [0] * (max_edges + 1)
                        dp[new_key] = dest

                    base_shift = s * (s - 1) // 2
                    for k in range(s + 1):
                        coeff = comb(s, k)
                        if (s - k) & 1:
                            coeff = -coeff
                        coeff = (coeff * ways) % P
                        shift = base_shift + prev * k
                        if coeff:
                            for q, val in enumerate(poly):
                                if val:
                                    idx = q + shift
                                    dest[idx] = (dest[idx] + val * coeff) % P
            else:
                remaining = n - a
                if remaining == 0:
                    continue
                for s in range(1, remaining + 1):
                    na, nb = a + s, b
                    ways = comb(remaining, s) % P
                    new_turn = 0
                    new_key = (na, nb, s, new_turn)

                    dest = dp.get(new_key)
                    if dest is None:
                        dest = [0] * (max_edges + 1)
                        dp[new_key] = dest

                    base_shift = s * (s - 1) // 2
                    for k in range(s + 1):
                        coeff = comb(s, k)
                        if (s - k) & 1:
                            coeff = -coeff
                        coeff = (coeff * ways) % P
                        shift = base_shift + prev * k
                        if coeff:
                            for q, val in enumerate(poly):
                                if val:
                                    idx = q + shift
                                    dest[idx] = (dest[idx] + val * coeff) % P

    # Sum all level decompositions in the variable t = 1 + z.
    total_poly = [0] * (max_edges + 1)
    for poly in final_polys:
        for i, v in enumerate(poly):
            total_poly[i] = (total_poly[i] + v) % P

    # Convert from powers of t = 1 + z to powers of z.
    binom_mod = [[0] * (max_edges + 1) for _ in range(max_edges + 1)]
    for i in range(max_edges + 1):
        binom_mod[i][0] = 1
        binom_mod[i][i] = 1
        for j in range(1, i):
            binom_mod[i][j] = (binom_mod[i - 1][j - 1] + binom_mod[i - 1][j]) % P

    partition_choices = comb(N - 1, n - 1) % P
    answers = []

    for m in range(N - 1, max_edges + 1):
        value = 0
        for q in range(m, max_edges + 1):
            value = (value + total_poly[q] * binom_mod[q][m]) % P
        answers.append(str(value * partition_choices % P))

    print(" ".join(answers))

if __name__ == "__main__":
    solve()

import sys


def matmul(a, b, mod):
    n = len(a)
    c = [[0] * n for _ in range(n)]
    for i in range(n):
        ci = c[i]
        ai = a[i]
        for k, aik in enumerate(ai):
            if aik:
                bk = b[k]
                for j in range(n):
                    ci[j] += aik * bk[j]
        for j in range(n):
            ci[j] %= mod
    return c


def mat_pow(a, e, mod):
    n = len(a)
    r = [[0] * n for _ in range(n)]
    for i in range(n):
        r[i][i] = 1

    while e:
        if e & 1:
            r = matmul(r, a, mod)
        e >>= 1
        if e:
            a = matmul(a, a, mod)
    return r


def solve():
    input = sys.stdin.readline
    n, p = map(int, input().split())
    a = [list(map(int, input().split())) for _ in range(n)]

    if p == 1:
        print("\n".join(["0"] * n))
        return

    # For p = 2, every zero is replaced by 1, and there is only one matrix.
    if p == 2:
        b = [[1 if a[i][j] == 0 else a[i][j] for j in range(n)]
             for i in range(n)]
        ans = matmul(b, b, p)
        print("\n".join(" ".join(map(str, row)) for row in ans))
        return

    zero_count = sum(row.count(0) for row in a)
    ans = mat_pow(a, p, p)

    # Contributions from a zero diagonal entry used p-1 times,
    # with one nonzero edge being used once.
    for u in range(n):
        if a[u][u] != 0:
            continue

        for j in range(n):
            if a[u][j] != 0:
                ans[u][j] += a[u][j]

        for i in range(n):
            if a[i][u] != 0:
                ans[i][u] += a[i][u]

    # For p = 3, a non-loop zero edge can occur twice with the reverse
    # nonzero edge between the two occurrences.
    if p == 3:
        for u in range(n):
            for v in range(n):
                if u != v and a[u][v] == 0 and a[v][u] != 0:
                    ans[u][u] += a[v][u]

    sign = 1 if zero_count % 2 == 0 else p - 1
    for i in range(n):
        for j in range(n):
            ans[i][j] = (ans[i][j] * sign) % p

    print("\n".join(" ".join(map(str, row)) for row in ans))


if __name__ == "__main__":
    solve()

class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7
        return (
            m
            * pow(m - 1, n - 1 - k, MOD)
            * __import__("math").comb(n - 1, k)
        ) % MOD

