class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def can(limit: int) -> bool:
            INF = 10**9

            dp0 = [INF] * (limit + 1)
            dp1 = [INF] * (limit + 1)

            if s[0] == '0':
                dp0[1] = 0
                dp1[1] = 1
            else:
                dp0[1] = 1
                dp1[1] = 0

            for ch in s[1:]:
                ndp0 = [INF] * (limit + 1)
                ndp1 = [INF] * (limit + 1)

                cost0 = 0 if ch == '0' else 1
                cost1 = 0 if ch == '1' else 1

                ndp0[1] = min(dp1) + cost0
                ndp1[1] = min(dp0) + cost1

                for length in range(1, limit):
                    ndp0[length + 1] = dp0[length] + cost0
                    ndp1[length + 1] = dp1[length] + cost1

                dp0, dp1 = ndp0, ndp1

            return min(min(dp0), min(dp1)) <= numOps

        left, right = 1, n

        while left < right:
            mid = (left + right) // 2
            if can(mid):
                right = mid
            else:
                left = mid + 1

        return left

import sys


def cross(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])


def main():
    input = sys.stdin.readline
    n = int(input())
    points = [tuple(map(int, input().split())) for _ in range(n)]

    # Upper convex hull of previously processed points.
    hull = []

    best_num = None
    best_den = 1

    for x, h in points:
        if hull:
            if len(hull) == 1:
                idx = 0
            else:
                lo, hi = 0, len(hull) - 1

                # Slopes from (x, h) to upper-hull points are unimodal.
                while lo < hi:
                    mid = (lo + hi) // 2
                    x1, h1 = hull[mid]
                    x2, h2 = hull[mid + 1]

                    left_num = (h - h1) * (x - x2)
                    right_num = (h - h2) * (x - x1)

                    if left_num <= right_num:
                        hi = mid
                    else:
                        lo = mid + 1

                idx = lo

            px, ph = hull[idx]

            # y-intercept of the line through (px, ph) and (x, h)
            cand_num = x * ph - px * h
            cand_den = x - px

            if best_num is None or cand_num * best_den > best_num * cand_den:
                best_num = cand_num
                best_den = cand_den

        hull.append((x, h))

        # Maintain the upper convex hull.
        while len(hull) >= 3 and cross(hull[-3], hull[-2], hull[-1]) >= 0:
            hull.pop(-2)

    if best_num is None or best_num < 0:
        print(-1)
    else:
        print("{:.15f}".format(best_num / best_den))


