def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:1 + n]

    max_sum = 2 * max(a)
    answer = 0
    h = 1

    while h <= max_sum:
        modulus = h << 1
        mask = modulus - 1

        groups = {}
        for x in a:
            r = x & mask
            if r in groups:
                groups[r][0] += 1
                groups[r][1] += x
            else:
                groups[r] = [1, x]

        for r, (count1, sum1) in groups.items():
            complement = (h - r) & mask

            if r < complement:
                group2 = groups.get(complement)
                if group2 is not None:
                    count2, sum2 = group2
                    answer += (sum1 * count2 + sum2 * count1) // h
            elif r == complement:
                answer += ((count1 + 1) * sum1) // h

        h <<= 1

    print(answer)

