import sys
from bisect import bisect_left

def build_chain(perm, balls, x, n):
    pos = [-1] * n
    order = []

    cur = x
    while True:
        cur = perm[cur]
        if cur == x:
            break
        pos[cur] = len(order)
        order.append(cur)

    start = len(order)
    for i in range(n):
        if balls[i] and i != x:
            if pos[i] == -1:
                return None
            start = min(start, pos[i])

    return order[start:] if start < len(order) else []

def lcs_length(a, b):
    positions = {v: i for i, v in enumerate(b)}
    tails = []

    for v in a:
        if v not in positions:
            continue
        x = positions[v]
        k = bisect_left(tails, x)
        if k == len(tails):
            tails.append(x)
        else:
            tails[k] = x

    return len(tails)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)

    n = next(it)
    x = next(it) - 1

    A = [next(it) for _ in range(n)]
    B = [next(it) for _ in range(n)]
    P = [next(it) - 1 for _ in range(n)]
    Q = [next(it) - 1 for _ in range(n)]

    red = build_chain(P, A, x, n)
    blue = build_chain(Q, B, x, n)

    if red is None or blue is None:
        print(-1)
        return

    common = lcs_length(red, blue)
    print(len(red) + len(blue) - common)

